source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    forms = [
        ("row", lambda r, c: r, [(0, 1)]),
        ("column", lambda r, c: c, [(1, 0)]),
        ("diag_sum", lambda r, c: r + c, [(1, -1)]),
        ("diag_diff", lambda r, c: r - c, [(1, 1)]),
    ]
    # Identify the direction of the colored guide lines from adjacent marks.
    scores = {}
    for name, coord, steps in forms:
        score = 0
        dr, dc = steps[0]
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                rr, cc = r + dr, c + dc
                if color != 0 and 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    score += 1
        scores[name] = score
    preferred = max(scores, key=scores.get)
    candidates = []
    for name, coord, _ in forms:
        for period in range(1, max(h, w) + 1):
            colors = {}
            valid = True
            for r in range(h):
                for c in range(w):
                    color = grid[r][c]
                    if color == 0:
                        continue
                    residue = coord(r, c) % period
                    if residue in colors and colors[residue] != color:
                        valid = False
                        break
                    colors[residue] = color
                if not valid:
                    break
            if valid and len(colors) == period:
                candidates.append((period, name, coord, colors))
    if not candidates:
        return [row[:] for row in grid]
    directed = [item for item in candidates if item[1] == preferred]
    choices = directed or candidates
    period, name, coord, colors = max(choices, key=lambda item: item[0])
    return [[colors[coord(r, c) % period] for c in range(w)] for r in range(h)]
'''
